<?php
/*
 * openDAW Custom Server
 *
 * Stores your openDAW backup on your own webspace. Generated by openDAW for you, do not share it.
 * Anyone who knows your token can read and delete your backup.
 *
 * THIS FILE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND. YOU RUN IT ON YOUR OWN SERVER AND ARE
 * RESPONSIBLE FOR ITS SECURITY, BACKUPS, LIMITS AND COSTS. openDAW ACCEPTS NO LIABILITY FOR DATA LOSS,
 * UNAUTHORISED ACCESS OR ANY OTHER DAMAGE ARISING FROM ITS USE.
 *
 * Requires PHP 7.4 or newer and HTTPS.
 */

declare(strict_types=1);

const VERSION = 1;
const TOKEN_HASH = '__TOKEN_HASH__';
const ORIGINS = ['__ORIGINS__'];
const DATA_FOLDER = '__DATA_FOLDER__';
const STALE_SECONDS = 86400;

error_reporting(0);
ini_set('display_errors', '0');

function respond(int $status, array $body): void
{
    http_response_code($status);
    header('Content-Type: application/json');
    header('Cache-Control: no-store');
    echo json_encode($body);
    exit;
}

function fail(int $status, string $error): void
{
    respond($status, ['error' => $error]);
}

function startsWith(string $text, string $prefix): bool
{
    return strncmp($text, $prefix, strlen($prefix)) === 0;
}

function isSecure(): bool
{
    if (!empty($_SERVER['HTTPS']) && strtolower((string)$_SERVER['HTTPS']) !== 'off') {return true;}
    if (strtolower((string)($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '')) === 'https') {return true;}
    $remote = (string)($_SERVER['REMOTE_ADDR'] ?? '');
    return $remote === '127.0.0.1' || $remote === '::1';
}

function dataRoot(): string
{
    $root = __DIR__ . '/' . DATA_FOLDER;
    if (!is_dir($root)) {
        if (!mkdir($root, 0755, true)) {fail(500, 'storage');}
        file_put_contents($root . '/index.html', '');
        file_put_contents($root . '/.htaccess', "<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n"
            . "<IfModule !mod_authz_core.c>\nOrder allow,deny\nDeny from all\n</IfModule>\n");
    }
    foreach (['/.tmp', '/.sessions'] as $folder) {
        if (!is_dir($root . $folder) && !mkdir($root . $folder, 0755)) {fail(500, 'storage');}
    }
    return $root;
}

function segments(string $path): array
{
    if ($path === '') {return [];}
    $parts = explode('/', $path);
    foreach ($parts as $part) {
        if ($part === '' || $part[0] === '.' || strlen($part) > 200
            || preg_match('/[\x00-\x1f\x7f\\\\:*?"<>|]/', $part) === 1) {
            fail(400, 'path');
        }
    }
    return $parts;
}

function folderPath(string $root, array $parts): string
{
    return count($parts) === 0 ? $root : $root . '/' . implode('/', $parts);
}

function filePath(string $root, array $parts): string
{
    if (count($parts) === 0) {fail(400, 'path');}
    return folderPath($root, $parts) . '.bin';
}

function ensureInside(string $root, string $folder): void
{
    $real = realpath($folder);
    $base = realpath($root);
    if ($real === false || $base === false || ($real !== $base && !startsWith($real, $base . '/'))) {
        fail(400, 'path');
    }
}

function ensureParent(string $root, array $parts): void
{
    $parent = folderPath($root, array_slice($parts, 0, -1));
    if (!is_dir($parent) && !mkdir($parent, 0755, true)) {fail(507, 'storage');}
    ensureInside($root, $parent);
}

function removeTree(string $path): bool
{
    if (is_link($path) || is_file($path)) {return unlink($path);}
    if (!is_dir($path)) {return true;}
    foreach (scandir($path) ?: [] as $name) {
        if ($name === '.' || $name === '..') {continue;}
        if (!removeTree($path . '/' . $name)) {return false;}
    }
    return rmdir($path);
}

function tempFile(string $root): string
{
    return $root . '/.tmp/' . bin2hex(random_bytes(16));
}

function receive(string $target): void
{
    $input = fopen('php://input', 'rb');
    $output = fopen($target, 'wb');
    if ($input === false || $output === false) {fail(507, 'storage');}
    $written = stream_copy_to_stream($input, $output);
    fclose($input);
    $closed = fclose($output);
    $expected = (int)($_SERVER['CONTENT_LENGTH'] ?? -1);
    if ($written === false || !$closed) {
        unlink($target);
        fail(507, 'storage');
    }
    if ($expected >= 0 && $written !== $expected) {
        unlink($target);
        fail(413, 'too-large');
    }
}

function place(string $temp, string $target): void
{
    if (is_dir(substr($target, 0, -4))) {
        unlink($temp);
        fail(409, 'is-folder');
    }
    if (!rename($temp, $target)) {
        unlink($temp);
        fail(507, 'storage');
    }
}

function sessionFolder(string $root): string
{
    $session = (string)($_GET['session'] ?? '');
    if (preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/', $session) !== 1) {
        fail(400, 'session');
    }
    return $root . '/.sessions/' . $session;
}

function intParam(string $name, int $min): int
{
    $value = (string)($_GET[$name] ?? '');
    if (preg_match('/^[0-9]{1,15}$/', $value) !== 1 || (int)$value < $min) {fail(400, $name);}
    return (int)$value;
}

function removeStale(string $folder): void
{
    $limit = time() - STALE_SECONDS;
    foreach (scandir($folder) ?: [] as $name) {
        if ($name === '.' || $name === '..') {continue;}
        $path = $folder . '/' . $name;
        $modified = filemtime($path);
        if ($modified !== false && $modified < $limit) {removeTree($path);}
    }
}

$origin = (string)($_SERVER['HTTP_ORIGIN'] ?? '');
if ($origin !== '') {
    if (!in_array($origin, ORIGINS, true)) {fail(403, 'origin');}
    header('Access-Control-Allow-Origin: ' . $origin);
    header('Vary: Origin');
}
if (($_SERVER['REQUEST_METHOD'] ?? '') === 'OPTIONS') {
    header('Access-Control-Allow-Methods: GET, POST');
    header('Access-Control-Allow-Headers: X-OpenDAW-Token, Content-Type');
    header('Access-Control-Max-Age: 86400');
    http_response_code(204);
    exit;
}
if (!isSecure()) {fail(403, 'https');}
if (strlen(TOKEN_HASH) !== 64) {fail(500, 'not-configured');}
$token = (string)($_SERVER['HTTP_X_OPENDAW_TOKEN'] ?? '');
if ($token === '' || !hash_equals(TOKEN_HASH, hash('sha256', $token))) {fail(401, 'token');}

$method = (string)($_SERVER['REQUEST_METHOD'] ?? '');
$action = (string)($_GET['action'] ?? '');
$reads = ['alive', 'exists', 'download', 'list'];
$writes = ['delete', 'upload', 'chunk', 'commit'];
if (in_array($action, $reads, true)) {
    if ($method !== 'GET') {fail(405, 'method');}
} elseif (in_array($action, $writes, true)) {
    if ($method !== 'POST') {fail(405, 'method');}
} else {
    fail(400, 'action');
}

$root = dataRoot();
$parts = segments((string)($_GET['path'] ?? ''));

switch ($action) {
    case 'alive':
        removeStale($root . '/.tmp');
        removeStale($root . '/.sessions');
        respond(200, ['version' => VERSION]);
    case 'exists':
        respond(200, ['exists' => count($parts) === 0
            || is_file(filePath($root, $parts)) || is_dir(folderPath($root, $parts))]);
    case 'download':
        $file = filePath($root, $parts);
        if (!is_file($file)) {fail(404, 'not-found');}
        while (ob_get_level() > 0) {ob_end_clean();}
        header('Content-Type: application/octet-stream');
        header('Content-Length: ' . filesize($file));
        header('Cache-Control: no-store');
        readfile($file);
        exit;
    case 'list':
        $folder = folderPath($root, $parts);
        $names = [];
        if (is_dir($folder)) {
            foreach (scandir($folder) ?: [] as $name) {
                if ($name[0] === '.' || $name === 'index.html') {continue;}
                if (is_dir($folder . '/' . $name)) {
                    $names[] = $name;
                } elseif (substr($name, -4) === '.bin') {
                    $names[] = substr($name, 0, -4);
                }
            }
        }
        respond(200, ['names' => $names]);
    case 'delete':
        if (count($parts) === 0) {fail(400, 'path');}
        $file = filePath($root, $parts);
        $folder = folderPath($root, $parts);
        if ((is_file($file) && !unlink($file)) || (is_dir($folder) && !removeTree($folder))) {fail(500, 'storage');}
        respond(200, []);
    case 'upload':
        $target = filePath($root, $parts);
        ensureParent($root, $parts);
        $temp = tempFile($root);
        receive($temp);
        place($temp, $target);
        respond(200, []);
    case 'chunk':
        $session = sessionFolder($root);
        $index = intParam('index', 0);
        if (!is_dir($session) && !mkdir($session, 0755)) {fail(507, 'storage');}
        $temp = tempFile($root);
        receive($temp);
        if (!rename($temp, $session . '/' . sprintf('%08d', $index))) {
            unlink($temp);
            fail(507, 'storage');
        }
        touch($session);
        respond(200, []);
    case 'commit':
        $target = filePath($root, $parts);
        $session = sessionFolder($root);
        $count = intParam('count', 1);
        $size = intParam('size', 0);
        if (!is_dir($session)) {
            if (is_file($target) && filesize($target) === $size) {respond(200, []);}
            fail(409, 'missing-chunk');
        }
        ensureParent($root, $parts);
        $temp = tempFile($root);
        $output = fopen($temp, 'wb');
        if ($output === false) {fail(507, 'storage');}
        $total = 0;
        for ($index = 0; $index < $count; $index++) {
            $chunk = $session . '/' . sprintf('%08d', $index);
            $input = is_file($chunk) ? fopen($chunk, 'rb') : false;
            if ($input === false) {
                fclose($output);
                unlink($temp);
                fail(409, 'missing-chunk');
            }
            $copied = stream_copy_to_stream($input, $output);
            fclose($input);
            if ($copied === false) {
                fclose($output);
                unlink($temp);
                fail(507, 'storage');
            }
            $total += $copied;
        }
        if (!fclose($output)) {
            unlink($temp);
            fail(507, 'storage');
        }
        if ($total !== $size) {
            unlink($temp);
            fail(409, 'size');
        }
        place($temp, $target);
        removeTree($session);
        respond(200, []);
}
